// Generated by philote from page /projects/[id]. Do not edit.
import type { Metadata } from "next";
import { notFound } from "next/navigation";
import { connection } from "next/server";
import { Suspense } from "react";

import { projects } from "@/lib/api";
import { readProjectView } from "@/lib/reads";

import ProjectView from "@/components/common/project-view";

export const metadata: Metadata = { title: "Project" };

export default function Page({ params }: PageProps<"/projects/[id]">) {
    return (
        <main className="flex-1 px-4 py-10">
            <div className="mx-auto max-w-4xl">
                <Suspense fallback={<p className="text-muted-foreground">Loading…</p>}>
                    <Record params={params} />
                </Suspense>
            </div>
        </main>
    );
}

// Record streams in after the page's shell, so a missing record renders
// not-found.tsx with noindex, but the response status stays 200.
async function Record({ params }: Pick<PageProps<"/projects/[id]">, "params">) {
    await connection();
    const { id } = await params;
    const result = await projects.get(id);
    if (!result.ok) {
        notFound();
    }
    const item = await readProjectView(result.value);
    return <ProjectView {...item} />;
}
